var paths=new[]{"Assets/_Game/Animations/Shared/Walking.fbx","Assets/_Game/Animations/Shared/Running.fbx","Assets/_Game/Animations/ThuyKieu/TK-Walking.fbx","Assets/_Game/Animations/ThuyKieu/TK-Running.fbx"};
return new { playing=Application.isPlaying, clips=paths.Select(path=>{var c=AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().First(x=>!x.name.StartsWith("__preview__"));return new{path,c.name,c.length,c.frameRate,c.isHumanMotion,c.isLooping,curves=AnimationUtility.GetCurveBindings(c).Where(b=>b.type==typeof(Animator)&& (b.propertyName.Contains("Leg")||b.propertyName.Contains("Arm")||b.propertyName.Contains("Spine")||b.propertyName.Contains("Root"))).Select(b=>{var curve=AnimationUtility.GetEditorCurve(c,b);return new{b.propertyName,count=curve.length,min=curve.keys.Min(k=>k.value),max=curve.keys.Max(k=>k.value)};}).ToArray()};}).ToArray()};
